func TestAssuranceVerifyLeaderSupporters(t *testing.T) {
	run := func(name string, alsoCutNonvoters bool) {
		conf := inmemConfig(t)
		conf.HeartbeatTimeout = time.Second
		conf.ElectionTimeout = time.Second
